import{_ as o,a0 as p,w as u,s as r,ao as x,I as a,x as e,a1 as s,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"2014年會是  Linux桌面年 嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"2014年會是  Linux桌面年 嗎？ | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2014年會是  Linux桌面年 嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2014年會是  Linux桌面年 嗎？ | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141211 Was 2014 The Year of Linux Desktop","title":"2014年會是  Linux桌面年 嗎？","tag":"201412","desc":""},"relativePath":"201412/20141211 Was 2014 The Year of Linux Desktop.md","filePath":"[post].md"}'),l={name:"201412/20141211 Was 2014 The Year of Linux Desktop.md"};function L(m,t,f,d,T,g){const i=p("Link");return u(),r("div",null,[t[13]||(t[13]=x('<h1 id="_2014年會是-linux桌面年-嗎" tabindex="-1">2014年會是 &quot;Linux桌面年&quot;嗎？ <a class="header-anchor" href="#_2014年會是-linux桌面年-嗎" aria-label="Permalink to “2014年會是 Linux桌面年嗎？”">​</a></h1><blockquote><p>Linux桌面現在終於發出最強音！</p></blockquote><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-2.jpg" alt=""></p><p><strong>看來Linux在2014年有很多改變，許多用户都表示今年Linux的確有進步，但是僅憑這個就能斷定2014年就是&quot;Linux桌面年&quot;嗎？</strong></p><p>&quot;Linux桌面年&quot;這句話，在過去幾年就被傳誦得像句頌歌一樣，可以説是在試圖用一種比較有意義的方式來標記它的發展進程。此類事情目前還沒有發生過，在我們的見證下也從無先例，所以這就不難理解為什麼Linux用户會用這個角度去看待這句話。</p><p>大多數軟件和硬件領域不太會有這種快速的進步，都以較慢的速度發展，但是對於那些在工業領域有更好眼光的人來説，事情就會變得瘋狂。即使有可能，針對某一時刻或某一事件還是比較困難的，但是Linux在幾年的過程中還是以指數方式迅速發展成長。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-3.jpg" alt=""></p><h3 id="linux桌面年這句話不可輕言" tabindex="-1">Linux桌面年這句話不可輕言 <a class="header-anchor" href="#linux桌面年這句話不可輕言" aria-label="Permalink to “Linux桌面年這句話不可輕言”">​</a></h3><p>沒有一個比較權威的人和機構能判定Linux桌面年已經到來或者已經過去，所以我們只能嘗試根據迄今為止我們所看到的和用户所反映的去推斷。有一些人比較保守，改變對他們影響不大，還有一些人則比較激進，永遠不知滿足。這真的要取決於你的見解了。</p><p>點燃這一切的火花似乎就是Linux上的Steam平台，儘管在這變成現實之前我們已經看到了一些Linux遊戲已經開始有重要的動作了。在任何情況下，Valve都可能是我們今天所看到的一系列復甦事件的催化劑。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-6.jpg" alt=""></p><p>在過去的十年裏，Linux桌面以一種緩慢的速度在發展，並沒有什麼真正的改變。創新肯定是有的，但是市場份額幾乎還是保持不變。無論桌面變得多麼酷或Linux相比之前的任何一版多出了多少特點，很大程度上還是在原地踏步，包括那些開發商業軟件的公司，他們的參與度一直很小，基本上就忽略掉了Linux。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-4.jpg" alt=""></p><p>現在，相比過去的十年裏，更多的公司表現出了對Linux平台的濃厚興趣。或許這是一種自然地演變，Valve並沒有做什麼，但是Linux最終還是達到了一個能被普通用户接受並理解的水平，並不只是因為令人着迷的開源技術。</p><p>驅動程序能力強了，遊戲工作室就會定期移植遊戲，在Linux中我們前所未見的應用和中間件就會開始出現。Linux內核發展達到了難以置信的速度，大多數發行版的安裝過程通常都不怎麼難，所有這一切都只是冰山一角。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-5.jpg" alt=""></p><p>所以，當有人問你2014年是不是Linux桌面年時，你可以説“是的！”，因為Linux桌面完全統治了2014年。</p><hr>',18)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),s(i,{href:"http://news.softpedia.com/news/Was-2014-The-Year-of-Linux-Desktop-467036.shtml"},{default:n(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/Was-2014-The-Year-of-Linux-Desktop-467036.shtml",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),s(i,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:n(()=>[...t[2]||(t[2]=[e("Silviu Stahie",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),s(i,{href:"https://github.com/ZTinoZ"},{default:n(()=>[...t[3]||(t[3]=[e("ZTinoZ",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),s(i,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const D=o(l,[["render",L]]);export{k as __pageData,D as default};
